345	const BANK_BUB_VERT = /* glsl */ `
346	varying vec2 vP;
347	varying vec3 vInst;
348	varying float vBig;
349	varying vec3 vCv;
350	varying float vR;
351	#include <fog_pars_vertex>
352	void main() {
353	  vec4 c = modelMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
354	  float r = length((instanceMatrix * vec4(1.0, 0.0, 0.0, 0.0)).xyz);
355	  vec4 mvPosition = viewMatrix * c;
356	  vCv = mvPosition.xyz;
357	  vR = r;
358	  // wave 7: 0 for bubbles <= ~18 px, 1 for >= ~40 px on screen (the ref's big near bumps show large white caps)
359	  vBig = smoothstep(0.012, 0.026, projectionMatrix[1][1] * r / max(-mvPosition.z, 0.01));
360	  mvPosition.xyz += normalize(-mvPosition.xyz) * r * 0.6;
361	  mvPosition.xy += position.xy * r;
362	  vP = position.xy;
363	  vInst = instanceColor;
364	  gl_Position = projectionMatrix * mvPosition;
365	  #include <fog_vertex>
366	}
367	`;
368	/**
369	 * wave 8 (05 only: rafts + the 05 berm puffs): one foam lump = a sphere impostor with the true per-pixel sphere depth,
370	 * so lumps sink into the water and into each other with curved creases (a merged low foam mound, not stacked discs);
371	 * the lower outline of larger lumps is scalloped by small piled bubbles; the micro texture packs tiny open bubbles on
372	 * the lower half / flanks; bubbles under ~14 px render as glossy little soap bubbles with a thin blue rim.
373	 */
374	const BANK_BUB_FRAG = /* glsl */ `
375	uniform mat4 projectionMatrix;
376	uniform vec3 uLightDir;
377	uniform float uTime;
378	varying vec2 vP;
379	varying vec3 vInst;
380	varying float vBig;
381	varying vec3 vCv;
382	varying float vR;
383	#include <fog_pars_fragment>
384	${NOISE_GLSL}
385	${SOAP05_GLSL}
386	${MICRO_GLSL}
387	void main() {
388	  float px = 2.0 / max(fwidth(vP.x), 1e-4);
389	  float d = length(vP);
390	  float ang = atan(vP.y, vP.x);
391	  float nS = clamp(floor(px / 8.0), 5.0, 16.0);
392	  float sc = abs(sin(ang * nS * 0.5 + vInst.y * 31.0));
393	  float amp = 0.11 * smoothstep(16.0, 34.0, px) * smoothstep(0.45, -0.35, vP.y / max(d, 1e-3));
394	  float R = 1.0 - amp * (1.0 - sc);
395	  if (d > R) discard;
396	  vec2 q = vP / R;
397	  float z = sqrt(max(1.0 - dot(q, q), 0.0));
398	  vec3 Nv = vec3(q, z);
399	  vec4 clip = projectionMatrix * vec4(vCv + vR * vec3(vP, z * R), 1.0);
400	  gl_FragDepth = 0.5 * clip.z / clip.w + 0.5;
401	  // wave 7 ramp: white top caps, lavender-white bodies, periwinkle / blue undersides; lower / side silhouette = the
402	  // blue-violet crevice between piled bubbles; inner / lower bubbles of a pile (ambient occlusion vInst.x) bluer
403	  // wave 8: steeper key light from the upper left (ref lumps: white caps only on the lit top, lavender middle, blue lower
404	  // half); soapT put a sphere's centre at t ~0.86 (near white), so the clumps read grey-white
405	  float tl = dot(Nv, normalize(vec3(-0.4, 0.85, 0.35)));
406	  float t = 0.52 + 0.62 * tl - pow(1.0 - z, 1.5) * (0.25 + 0.35 * clamp(0.5 - q.y * 0.7, 0.0, 1.0)) - (1.0 - vInst.x) * 0.3 + 0.06 * vBig;
407	  // fine open bubbles: dense on the lower half and the flanks, sparse on the lit top
408	  vec2 mp = q * (1.0 + 0.6 * (1.0 - z)) * clamp(px / 8.0, 1.2, 12.0) + vInst.y * 37.0;
409	  float dens = clamp(0.25 + 0.9 * smoothstep(0.35, -0.6, q.y) + 0.35 * (1.0 - z) - 0.2 * vBig, 0.0, 0.95);
410	  vec4 mf = microFoam(mp, dens);
411	  float kf = 1.0 - smoothstep(0.5, 0.9, fwidth(mp.x) + fwidth(mp.y));
412	  // wave 8 (it04): tone S-curve: few grey mid-tones, a broad white-lavender lit area and clearly blue shading
413	  // it05: the shading boundary sits higher (it04's 0.2..0.9 curve turned 50 % of the clump px pure white)
414	  // it06: boundary lower again (it05 clump boxes W 27-59 %, ref 22-28 %), no white bonus for big lumps
415	  t = 0.12 + 0.95 * smoothstep(0.38, 1.12, t - 0.06 * vBig);
416	  t += (mf.z - 0.6) * 0.2 * dens * kf - mf.x * 0.55 * kf + mf.y * 0.3 * kf;
417	  vec3 col = soap05(t + 0.04 * vInst.z);
418	  col = mix(col, vec3(1.0, 0.97, 1.07), smoothstep(0.75, 1.0, t) * 0.3);
419	  col += vec3(1.0) * mf.w * 0.45 * kf;
420	  vec3 Lv = (viewMatrix * vec4(normalize(uLightDir), 0.0)).xyz;
421	  float rl = max(dot(reflect(vec3(0.0, 0.0, -1.0), Nv), Lv), 0.0);
422	  col += vec3(1.0) * (pow(rl, 24.0) * 0.25 + pow(rl, 6.0) * 0.1);
423	  // tiny bubbles: lavender-white glossy body, thin blue rim, white speck (the lace at the ref waterlines)
424	  float tiny = 1.0 - smoothstep(9.0, 16.0, px);
425	  vec2 qs = vP - vec2(-0.32, 0.34);
426	  vec3 cb = mix(soap05(0.8 + 0.1 * vInst.z), soap05(0.12), smoothstep(0.5, 0.95, d)) + vec3(1.0) * exp(-dot(qs, qs) * 14.0) * 0.55;
427	  col = mix(col, cb, tiny);
428	  gl_FragColor = vec4(col, 1.0);
429	  ${FRAG_TAIL}
430	}
431	`;
