442	/** unit sphere puff with smooth normals (detail 0 icosahedra get flat normals by default) */
443	function puffGeometry(detail: number) {
444	  const g = new THREE.IcosahedronGeometry(1, detail);
445	  const p = g.attributes.position as THREE.BufferAttribute;
446	  const n = g.attributes.normal as THREE.BufferAttribute;
447	  const v = new THREE.Vector3();
448	  for (let i = 0; i < p.count; i++) { v.fromBufferAttribute(p, i).normalize(); n.setXYZ(i, v.x, v.y, v.z); }
449	  return g;
450	}
