471	// ---------------------------------------------------------------------------------- flank banks (05)
472	/**
473	 * In 05 the stream fills the tube floor wall to wall (S05.extent), so from the locked chase camera the
474	 * real stream edges and their berm leave the frame below y≈800 and the near field shows only open water.
475	 * Ref 05 has white cloud banks hugging BOTH sides all the way down to Benny's level (left x≈0–330 over
476	 * y≈540–1300, right x≈560–864). Wave 4: one continuous bank per side, fitted to the frame edges each
477	 * frame from the camera (so it holds for any device aspect), not floating islands:
478	 *  - a lather sheet (berm shader) from just below the frame bottom (ds −3.4) up the side of the frame
479	 *    until it merges into the berm (ds +15); its inner edge sits BANK_PX px in from the frame edge
480	 *    (lumpy, slow noise along s) and dips just under the water so the stream cuts a natural waterline;
481	 *  - instanced puffs (rim, crest, heaps) anchored to world cells along s, so the bank stays put on the
482	 *    water like the berm and Benny rides past it; they give the lumpy cloud silhouette.
483	 * Never closer than BANK_CLEAR_RIDER to Benny (near him) or BANK_CLEAR_CORE to the cyan core / coin line.
484	 */
485	const BANK_DS0 = -3.4;
486	const BANK_DS1 = 15;
487	/** puffs stop here (further ahead the berm and its own puffs take over) */
488	const BANK_PUFF_DS1 = 12.5;
489	/** inner edge of a clump at its widest: px in from the frame edge (of an 864-px wide frame), L / R */
490	const BANK_PX: [number, number] = [170, 200];
491	/** lateral size of a clump (px): a clump whose inner edge lies further in than this floats off the frame
492	 * edge with water beyond it (ref 05 lower clumps x≈50–200 and 610–790) */
493	const CLUMP_PX = 135;
494	/**
495	 * The flank lather SHEET (berm shader) read as flat white paper with straight cut edges at the clump ends;
496	 * the ref clumps are piled bubbles only, so wave 5 hides it and the impostor bubbles carry the clumps.
497	 */
498	const FLANK_SHEET = false;
499	/**
500	 * Wave 5: world-anchored clump envelope per side, [seed, frequency along s, threshold]. The near-field bank is a
501	 * chain of separate LOW clumps with open water between them (ref 05: left clumps y≈1016–1108 and
502	 * 1202–1330, right y≈800–950 and 1217–1300), not a continuous strip up the frame edge (wave 4 read as
503	 * a white wall: the outer 40 px were foam on 74 % / 100 % of the rows y 700–1400). The seeds put the
504	 * clumps of the QA frame (s≈132.4) where the ref has them; along 05 clumps cover ≈40 % of the length.
505	 */
506	const BANK_ENV: [number, number, number][] = [[58.457, 0.835, 0.581], [607.242, 0.459, 0.357], [267.601, 1.094, 0.563]];
507	/**
508	 * wave 7 (ref 05 rows, qa/pilot05/wave7/foam): the bank row's inner edge (px in from the frame edge) and lateral size
509	 * (px) by row ds. The right bank ahead of Benny is a NARROW rim hugging the river edge (ref y 700-940: inner edge
510	 * 30 -> 158 -> 70 px, 20-66 px per row), not the wave-5 heap (124-179 px per row). The ref's near clumps: left x 0-130
511	 * y 1020-1110 (ds 0.5-1.5), lower left x 60-230 y 1220-1300 and lower right x 650-800 y 1260-1330 (behind Benny,
512	 * ds -1.1..-1.7). The envelope seeds
513	 * (BANK_ENV, searched; [2] = right side beside / behind Benny) open/close the clumps at those rows of the QA frame.
514	 */
515	const RIM_R: [number, number][] = [[2.6, 60], [3.4, 70], [4.4, 105], [5.5, 140], [6.6, 158], [7.8, 153], [9.0, 135], [10.3, 104], [11.6, 70], [12.9, 30]];
516	const RIM_R_PX = 80;
517	function rimR(ds: number): number {
518	  if (ds <= RIM_R[0][0]) return RIM_R[0][1];
519	  for (let i = 1; i < RIM_R.length; i++) {
520	    if (ds <= RIM_R[i][0]) {
521	      const [a, pa] = RIM_R[i - 1], [b, pb] = RIM_R[i];
522	      return pa + ((pb - pa) * (ds - a)) / (b - a);
523	    }
524	  }
525	  return RIM_R[RIM_R.length - 1][1];
526	}
527	const BANK_CLEAR_RIDER = 1.3;
528	const BANK_CLEAR_CORE = 1.45;
