530	/**
531	 * wave 5: 0.4 in 05 (smooth ramps at the stage ends), 1 elsewhere. In 05 the stream-edge rim toward the VP
532	 * is a LOW band of piled bubbles (ref ≈40–60 px); the full-height berm read as tall white heaps.
533	 */
534	function bermScale05(course: Course): (s: number) => number {
535	  const st = course.stage('05');
536	  const sm = (a: number, b: number, x: number) => { const u = Math.min(1, Math.max(0, (x - a) / (b - a))); return u * u * (3 - 2 * u); };
537	  return (s) => 1 - 0.6 * sm(st.s0 - 6, st.s0 - 1, s) * (1 - sm(st.s1 - 1, st.s1 + 4, s));
538	}
539	/** squash the part of the bank above the stream's edge water level by k (k = 1: unchanged) */
540	const squashBerm = (h: number, k: number) => (k < 1 && h > EDGE_LIFT ? EDGE_LIFT + (h - EDGE_LIFT) * k : h);
