542	/** continuous lather bank along both stream edges (skips the 03 whirlpool interior) */
543	function createBerm(course: Course, s0: number, s1: number, skip: [number, number], quality: 'high' | 'low') {
544	  const hk = bermScale05(course);
545	  const ds = quality === 'high' ? 0.32 : 0.8;
546	  const E = quality === 'high' ? [BERM_IN, -0.4, -0.25, -0.1, 0.04, 0.18, 0.34, 0.52, 0.75, 0.98, BERM_OUT] : [BERM_IN, -0.2, 0.15, 0.55, BERM_OUT];
547	  const rows = Math.ceil((s1 - s0) / ds) + 1;
548	  const C = E.length;
549	  const n = rows * C * 2;
550	  const pos = new Float32Array(n * 3);
551	  const foam = new Float32Array(n * 3);
552	  const tmp = new THREE.Vector3();
553	  let k = 0;
554	  const rowS: number[] = [];
555	  for (let i = 0; i < rows; i++) {
556	    const s = Math.min(s1, s0 + i * ds);
557	    rowS.push(s);
558	    const f = course.sample(s);
559	    const hw = course.widthAt(s) / 2;
560	    for (const side of [-1, 1]) {
561	      for (let j = 0; j < C; j++) {
562	        // left side is mirrored so every row runs inner → outer; bubble domes everywhere except
563	        // at the water line (keeps the lace edge flush with the stream)
564	        const e = E[j];
565	        const k05 = hk(s);
566	        const h = squashBerm(bermSurface(s, e, side, hw), k05);
567	        // 05: the outer (dry) side is laterally compressed too, so the rim is a narrow band of bubbles
568	        const eS = e > 0 ? e * (0.1 + 0.9 * k05) : e;
569	        tmp.copy(f.pos).addScaledVector(f.right, side * (hw + eS)).addScaledVector(f.up, h);
570	        tmp.toArray(pos, k * 3);
571	        foam[k * 3] = e;
572	        foam[k * 3 + 1] = s;
573	        foam[k * 3 + 2] = side;
574	        k++;
575	      }
576	    }
577	  }
578	  const idx: number[] = [];
579	  const rowStride = C * 2;
580	  for (let i = 0; i < rows - 1; i++) {
581	    const sa = rowS[i], sb = rowS[i + 1];
582	    if (sb > skip[0] && sa < skip[1]) continue;
583	    for (let sideI = 0; sideI < 2; sideI++) {
584	      for (let j = 0; j < C - 1; j++) {
585	        const a = i * rowStride + sideI * C + j, b = a + 1, c = a + rowStride, d = c + 1;
586	        // CCW seen from above on both sides (side +1 runs +right, side −1 runs −right)
587	        if (sideI === 1) idx.push(a, b, c, b, d, c);
588	        else idx.push(a, c, b, b, c, d);
589	      }
590	    }
591	  }
592	  const geo = new THREE.BufferGeometry();
593	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
594	  geo.setAttribute('aFoam', new THREE.BufferAttribute(foam, 3));
595	  geo.setIndex(idx);
596	  geo.computeVertexNormals();
597	  const st05 = course.stage('05');
598	  const uniforms = withFog({
599	    uTime: { value: 0 },
600	    uOutro: { value: new THREE.Vector2(0, course.stage('08').s0) },
601	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
602	    // colour starts at the 05 stage start (not s0 - 6 like the squash) so the 04 frame keeps its own foam colours
603	    uSt05: { value: new THREE.Vector4(st05.s0 - 1, st05.s0 + 2, st05.s1 - 1, st05.s1 + 4) },
604	  });
605	  const mat = new THREE.ShaderMaterial({
606	    uniforms,
607	    vertexShader: BERM_VERT,
608	    fragmentShader: BERM_FRAG,
609	    fog: true,
610	    side: THREE.DoubleSide,
611	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
612	  });
613	  const mesh = new THREE.Mesh(geo, mat);
614	  mesh.name = 'foam_berm';
615	  mesh.frustumCulled = false;
616	  return { mesh, uniforms };
617	}
