619	export function createFoam(
620	  course: Course,
621	  opts: { s0: number; s1: number; quality: 'high' | 'low'; height?: (s: number, lat: number, t: number) => number },
622	): FoamSystem {
623	  const { s0, s1, quality } = opts;
624	  const heightAt = opts.height ?? (() => 0);
625	  const rand = rng(1337);
626	  const density = quality === 'high' ? 1 : 0.5;
627	  // LOD: 80-tri puffs in the chunks around Benny, 20-tri puffs further out (low tier: 20-tri only)
628	  const geoHi = puffGeometry(quality === 'high' ? 1 : 0);
629	  const geoLo = quality === 'high' ? puffGeometry(0) : geoHi;
630	  const puff = makePuffMaterial(quality);
631	  const mat = puff.mat;
632	  const group = new THREE.Group();
633	  group.name = 'foam_banks';
634	  const st03 = course.stage('03'), st04 = course.stage('04');
635	  const chunkLen = 24;
636	  const chunks: { mesh: THREE.InstancedMesh; sa: number; sb: number }[] = [];
637	  let total = 0;
638	  const tmpM = new THREE.Matrix4();
639	  const tmpQ = new THREE.Quaternion();
640	  const tmpS = new THREE.Vector3();
641	  const tmpE = new THREE.Euler();
642	  const tmpC = new THREE.Color();
643	
644	  /** wave 8: the 05 berm puffs (Puff.imp) go to one impostor list (fine-foam shader, 2 tris each), see imp05 below */
645	  const imp05: { p: THREE.Vector3; r: number; c: [number, number, number] }[] = [];
646	  const build = (list: Puff[], parent: THREE.Object3D, sa: number, sb: number) => {
647	    if (!list.length) return;
648	    const nMesh = list.reduce((n, pf) => n + (pf.imp ? 0 : 1), 0);
649	    const mesh = nMesh ? new THREE.InstancedMesh(geoHi, mat, nMesh) : null;
650	    let i = 0;
651	    // the same rand() calls per puff whichever list it lands in, so every other stage's foam stays identical
652	    for (const pf of list) {
653	      tmpQ.setFromEuler(tmpE.set(rand() * 6, rand() * 6, rand() * 6));
654	      tmpS.set(pf.r, pf.r * (0.78 + rand() * 0.22), pf.r);
655	      const seed = rand();
656	      if (pf.imp) { imp05.push({ p: pf.p, r: pf.r, c: [pf.ao, seed, pf.tint] }); continue; }
657	      tmpM.compose(pf.p, tmpQ, tmpS);
658	      mesh!.setMatrixAt(i, tmpM);
659	      // x = ao + 2 q (q = 05 soap-shading weight x 8, see PUFF_VERT)
660	      mesh!.setColorAt(i, tmpC.setRGB(pf.ao + 2 * Math.round(Math.min(1, Math.max(0, pf.w5 ?? 0)) * 8), seed, pf.tint));
661	      i++;
662	    }
663	    if (!mesh) return;
664	    mesh.instanceMatrix.needsUpdate = true;
665	    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
666	    mesh.computeBoundingSphere();
667	    parent.add(mesh);
668	    chunks.push({ mesh, sa, sb });
669	    total += nMesh;
670	  };
671	
672	  // ---- continuous lather bank (berm) along both edges ----
673	  const skip: [number, number] = [st03.s0 + 4, st04.s0 - 6];
674	  const berm = createBerm(course, s0, s1, skip, quality);
675	  group.add(berm.mesh);
676	
677	  // ---- cloud banks of puffs hugging both stream edges (ref 05: 10–40 px white-lavender clumps) ----
678	  const inSkip = (s: number) => s > skip[0] && s < skip[1];
679	  // wave 5: in 05 the stream-edge rim toward the VP is a LOW rim of piled bubbles (ref ≈40–60 px), not
680	  // tall heaps: crest puffs × 0.85, heaps × 0.6 and never stacked. Only sizes change, so the shared
681	  // rand() sequence (and every other stage's foam) stays identical.
682	  const st05b = course.stage('05');
683	  const bermK = bermScale05(course);
684	  const low05 = (s: number) => s > st05b.s0 - 4 && s < st05b.s1 + 2;
685	  /** wave 8: berm puffs drawn as fine-foam impostors (full 05 soap weight only, so 04 / 06 keep their sphere puffs) */
686	  const imp05S = (s: number) => s > st05b.s0 + 2 && s < st05b.s1 - 2;
687	  const bermPoint = (ss: number, e: number, side: number, lift: number) => {
688	    const f = course.sample(ss);
689	    const hw = course.widthAt(ss) / 2;
