21	/**
22	 * Jet layout shared with the spray droplets (index.ts): across a = 0 (outer, most sideways jet) … 1
23	 * (inner, most backward jet). Angles in radians measured from straight back (towards the chase camera).
24	 * Ref 05 at the live camera (≈185 px per lateral unit, ≈100 px per unit back at Benny): the outer jets
25	 * leave at ≈32° below the horizontal on screen (≈41° from back in the world), the inner ones at ≈67°
26	 * (≈13° from back).
27	 */
28	export const FAN = {
29	  /** root angle on the root circle (ref 05 roots ≈(330, 1180) / (540, 1170): ≈0.5 u out, 0.3 u back) */
30	  root0: 1.25,
31	  root1: 0.72,
32	  /** jet direction */
33	  dir0: 0.78,
34	  dir1: 0.1,
35	  /** jets start at the fur skirt, not under the body: root circle radius ≥ this (units) */
36	  rootMin: 0.56,
