41	const VERT = /* glsl */ `
42	attribute vec2 aUV;      // x: 0 tail .. 1 head (along the streak), y: -1..1 across
43	attribute vec4 aJet;     // x: side (-1 / 1), y: across a (0 outer .. 1 inner), z: phase, w: seed
44	uniform float uTime;
45	uniform float uR;        // waterline radius of Benny's body (units): jet roots sit on this circle
46	uniform float uLen;      // max jet length (units)
47	uniform float uH;        // max arc height (units)
48	uniform float uStrength; // 0..1
49	varying vec2 vUV;
50	varying float vTau;
51	varying float vSeed;
52	varying float vFroth;
53	#include <fog_pars_vertex>
54	float hs(float n) { return fract(sin(n * 91.345 + 3.17) * 43758.5453); }
55	vec3 jetPos(float tau, float side, float a, float seed, float froth) {
56	  float thR = mix(${FAN.root0.toFixed(3)}, ${FAN.root1.toFixed(3)}, a) + (hs(seed * 3.1) - 0.5) * 0.14;
57	  // jets curl slightly outward as they fly (ref: the outer streaks bend towards the banks)
58	  float phi = mix(${FAN.dir0.toFixed(3)}, ${FAN.dir1.toFixed(3)}, a) + (hs(seed * 5.7) - 0.5) * 0.3 + 0.18 * tau;
59	  vec2 root = vec2(sin(thR), cos(thR)) * max(uR, ${FAN.rootMin.toFixed(3)}) * (0.9 + 0.12 * hs(seed * 2.3));
60	  float len = uLen * (0.6 + 0.4 * hs(seed * 7.3)) * (0.85 + 0.15 * sin(3.14159 * a)) * (0.55 + 0.45 * uStrength);
61	  len *= mix(1.0, 0.5, froth);
62	  vec2 q = root + vec2(sin(phi), cos(phi)) * tau * len;
63	  // most jets skim low over the water (ref: a flat fan), one in five is flung up as a high arc
64	  float tall = step(0.8, hs(seed * 29.3));
65	  float H = uH * mix(0.22 + 0.4 * hs(seed * 9.1), 1.0 + 0.35 * hs(seed * 9.1), tall) * (1.1 - 0.4 * a) * uStrength * mix(1.0, 0.4, froth);
66	  float tp = pow(max(tau, 0.0), 0.7);
67	  float y = H * 4.0 * tp * (1.0 - tp) - 0.012;
68	  return vec3(side * q.x, y, q.y);
69	}
70	void main() {
71	  float side = aJet.x;
72	  float a = aJet.y;
73	  float seed = aJet.w;
74	  float froth = step(0.6, hs(seed * 17.9));
75	  // life cycle: the streak's head runs from the root (tau 0) to the landing point (tau 1)
76	  float rate = mix(1.5, 2.5, hs(seed * 11.3)) * mix(1.0, 1.4, froth);
77	  float cyc = fract(aJet.z + uTime * rate);
78	  float tl = mix(0.22, 0.5, hs(seed * 13.7)) * mix(1.0, 0.6, froth);
79	  float head = cyc * (1.0 + tl);
80	  float tau = clamp(head - (1.0 - aUV.x) * tl, 0.0, 1.0);
81	  vec3 p = jetPos(tau, side, a, seed, froth);
82	  vec3 tg = jetPos(min(tau + 0.03, 1.0), side, a, seed, froth) - jetPos(max(tau - 0.03, 0.0), side, a, seed, froth);
83	  vec4 mvPosition = modelViewMatrix * vec4(p, 1.0);
84	  vec2 tv = (modelViewMatrix * vec4(tg, 0.0)).xy;
85	  float tl2 = length(tv);
86	  vec2 nrm = tl2 > 1e-5 ? vec2(-tv.y, tv.x) / tl2 : vec2(0.0, 1.0);
87	  // thin jets (≈2–5 px wide at Benny's distance), wider soft froth; tapered tail, round head
88	  float w = mix(mix(0.011, 0.024, hs(seed * 19.1)), mix(0.05, 0.095, hs(seed * 23.3)), froth);
89	  w *= mix(0.35, 1.0, smoothstep(0.0, 0.7, aUV.x)) * (0.7 + 0.3 * uStrength);
90	  mvPosition.xy += nrm * aUV.y * w;
