100	const FRAG = /* glsl */ `
101	uniform float uStrength;
102	varying vec2 vUV;
103	varying float vTau;
104	varying float vSeed;
105	varying float vFroth;
106	#include <fog_pars_fragment>
107	${NOISE_GLSL}
108	void main() {
109	  float ac = abs(vUV.y);
110	  float across = 1.0 - smoothstep(0.25, 1.0, ac);
111	  float along = smoothstep(0.0, 0.75, vUV.x);
112	  // fade in as it leaves the water under the fur, fade out as it falls back in
113	  float life = smoothstep(0.0, 0.1, vTau) * (1.0 - smoothstep(0.78, 1.0, vTau));
114	  // late in flight the jet breaks into droplet beads
115	  float bead = 1.0 - smoothstep(0.18, 0.42, abs(fract(vUV.x * 3.0 + vSeed * 7.0) - 0.5));
116	  float breakup = smoothstep(0.42, 0.75, vTau);
117	  float jet = across * along * mix(1.0, bead, breakup);
118	  // froth: bubbly white lace (open cells), soft all round
119	  float lc = cells(vec2(vUV.x * 2.6 + vSeed * 31.0, vUV.y * 1.3 + vSeed * 17.0));
120	  float lace = (1.0 - smoothstep(0.25, 0.55, lc)) * (1.0 - smoothstep(0.5, 1.0, ac)) * smoothstep(0.0, 0.35, vUV.x);
121	  float k = mix(jet, lace, vFroth);
122	  float alpha = k * life * uStrength * mix(0.95, 0.75, vFroth);
123	  if (alpha < 0.015) discard;
124	  // white core, cyan translucent edges; froth slightly lavender in its crevices
125	  vec3 cyan = vec3(0.42, 0.86, 1.0);
126	  vec3 white = vec3(1.12, 1.14, 1.18);
127	  vec3 col = mix(cyan, white, mix(smoothstep(0.1, 0.9, across) * (0.55 + 0.45 * along), 0.85, vFroth));
128	  col = mix(col, vec3(0.86, 0.84, 1.06), vFroth * smoothstep(0.15, 0.4, lc) * 0.35);
129	  gl_FragColor = vec4(col, alpha);
130	  ${FRAG_TAIL}
131	}
132	`;
