142	export function createRiderSplash(quality: 'high' | 'low'): RiderSplash {
143	  const perSide = quality === 'high' ? 150 : 60;
144	  // base strip: SEG segments along, 2 vertices across
145	  const uvs = new Float32Array((SEG + 1) * 2 * 2);
146	  for (let i = 0; i <= SEG; i++) {
147	    uvs.set([i / SEG, -1, i / SEG, 1], i * 4);
148	  }
149	  const idx: number[] = [];
150	  for (let i = 0; i < SEG; i++) {
151	    const a = i * 2, b = a + 1, c = a + 2, d = a + 3;
152	    idx.push(a, c, b, b, c, d);
153	  }
154	  const geo = new THREE.InstancedBufferGeometry();
155	  geo.setAttribute('aUV', new THREE.BufferAttribute(uvs, 2));
156	  // dummy position attribute (positions are generated in the vertex shader)
157	  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array((SEG + 1) * 2 * 3), 3));
158	  geo.setIndex(idx);
159	  const n = perSide * 2;
160	  const jet = new Float32Array(n * 4);
161	  // deterministic layout: stratified across the fan, golden-ratio phases (no clumping in a frozen frame)
162	  let k = 0;
163	  for (const side of [-1, 1]) {
164	    for (let i = 0; i < perSide; i++) {
165	      const h = (x: number) => { const v = Math.sin(x * 127.1 + side * 311.7) * 43758.5453; return v - Math.floor(v); };
166	      const a = Math.min(1, Math.max(0, (i + h(i * 1.7)) / perSide));
167	      jet[k++] = side;
168	      // denser towards the middle of the fan, thinner at both borders
169	      jet[k++] = 0.5 + (a - 0.5) * (0.75 + 0.25 * Math.abs(a - 0.5) * 2);
170	      jet[k++] = (i * 0.6180339 + h(i * 3.3) * 0.25) % 1;
171	      jet[k++] = h(i * 5.1 + 0.37);
172	    }
173	  }
174	  geo.setAttribute('aJet', new THREE.InstancedBufferAttribute(jet, 4));
175	  geo.instanceCount = n;
176	  const uniforms = withFog({ uTime: { value: 0 }, uR: { value: 0.45 }, uLen: { value: 1.25 }, uH: { value: 0.34 }, uStrength: { value: 0 } });
177	  const mat = new THREE.ShaderMaterial({
178	    uniforms,
179	    vertexShader: VERT,
180	    fragmentShader: FRAG,
181	    fog: true,
182	    transparent: true,
183	    depthWrite: false,
184	    side: THREE.DoubleSide,
185	  });
186	  const mesh = new THREE.Mesh(geo, mat);
187	  mesh.name = 'rider_splash';
188	  mesh.frustumCulled = false;
189	  mesh.renderOrder = 3;
190	  mesh.visible = false;
191	  const basis = new THREE.Matrix4();
192	  const back = new THREE.Vector3();
193	  const side = new THREE.Vector3();
194	  let target = 0;
195	  let fed = false;
196	  return {
