259	  float phi = mix(1.2, 0.45, a) + (hs(seed * 5.7) - 0.5) * 0.35;
260	  vec2 root = vec2(sin(thR), cos(thR)) * max(uR, 0.5) * 1.4;
261	  float len = (0.3 + 0.5 * hs(seed * 7.3)) * (0.55 + 0.45 * uStrength);
